// CrowdRelay decided WHO hears from us, WHICH message, and that consent
// and cooldown allow it. This workflow renders the named template and sends
// it to one fan. It never chooses a different template, broadens the
// recipient, or sends a message CrowdRelay did not request.
const e = $json;
if (!e || e.type !== 'crowdrelay.fan_lifecycle.message_requested' || e.version !== 1) return [];
const d = e.data ?? {};
for (const key of ['action_id', 'fan_id', 'template_key']) {
  if (!d[key]) throw new Error('lifecycle request missing ' + key);
}
const fan = d.fan ?? {};
const brand = d.brand ?? {};
if (!fan.email || !fan.email.includes('@')) throw new Error('invalid fan.email');
if (!brand.wordmark || !String(brand.wordmark).trim()) throw new Error('lifecycle request missing brand.wordmark');
return [{ json: {
  action_id: String(d.action_id),
  fan_id: String(d.fan_id),
  template_key: String(d.template_key),
  email: String(fan.email),
  display_name: fan.display_name || '',
  locale: String(fan.locale || ''),
  wordmark: String(brand.wordmark).trim(),
  referral_code: fan.referral_code || null,
  referral_url: fan.referral_url || null,
  install_url: fan.install_url || null,
  activation: fan.activation || null,
  show_title: fan.show_title || null,
  show_url: fan.show_url || null,
}}];

// Fail closed. Only `claimed` may send; `already_succeeded` is a no-op
// replay; `in_flight` and `ambiguous` require reconciliation instead of a
// second send.
const c = $input.first().json;
const plan = $('Validate lifecycle request').first().json;
if (c.status === 'already_succeeded') return [];
if (c.status !== 'claimed') throw new Error('claim not granted: ' + c.status);
return [{ json: { ...plan, claim_token: c.claim_token } }];

// Render the named template from tenant identity and fan locale.
// CrowdRelay owns brand identity and referral URLs. The executor must not
// compile in a band's name or construct a hostname.
// Throw on a key you do not know.
const p = $input.first().json;
const key = p.template_key;
const name = p.display_name || '';
const brand = String(p.wordmark || '').trim();
if (!brand) throw new Error('lifecycle render missing wordmark');
const pl = String(p.locale || '').toLowerCase().startsWith('pl');
const hello = pl
  ? (name ? ('Cześć ' + name) : 'Cześć')
  : (name ? ('Hi ' + name) : 'Hi');
const sign = '- ' + brand;
let subject, text;
if (key === 'crowdrelay.fan.welcome.v2') {
  const a = p.activation;
  if (a && (!['event','video'].includes(a.kind) || !a.title || !a.url || !/^https?:\/\//.test(a.url))) {
    throw new Error('invalid welcome activation');
  }
  subject = pl ? ('Dobrze, że jesteś — ' + brand) : ('Glad you are here — ' + brand);
  const next = !a ? [] : (pl
    ? ['', a.kind === 'event' ? 'Jeśli chcesz spotkać się pod sceną, tutaj są szczegóły:' : 'Zacznij od tego materiału:', a.title, '', a.url]
    : ['', a.kind === 'event' ? 'If you would like to meet us at a show, the details are here:' : 'Start with this video:', a.title, '', a.url]);
  text = [hello + ',', '', pl ? 'Dzięki, że do nas dołączasz.' : 'Thanks for joining us.', ...next, '', sign].join('\n');
} else if (key === 'crowdrelay.fan.welcome.v1') {
  subject = pl ? ('Witamy w ' + brand) : ('Welcome to ' + brand);
  text = pl
    ? [hello + ',', '', 'Dziękujemy za dołączenie. Od teraz koncerty, wiadomości i polecenia są w jednym miejscu.', '', sign].join('\n')
    : [hello + ',', '', 'Thanks for joining. From here, shows, updates and referrals stay in one place.', '', sign].join('\n');
} else if (key === 'crowdrelay.synesthesia.follow_up.v1') {
  subject = pl ? 'Dziękujemy za udział' : 'Thanks for taking part';
  text = pl
    ? [hello + ',', '', 'Dziękujemy za udział. Jeśli chcesz zrobić następny krok, zobaczmy się na koncercie.', '', sign].join('\n')
    : [hello + ',', '', 'Thanks for taking part. If you want a next step, come see us at a show.', '', sign].join('\n');
} else if (key === 'crowdrelay.fan.reactivation.v1') {
  subject = pl ? (brand + ' — co słychać?') : (brand + ' — it has been a while');
  text = pl
    ? [hello + ',', '', 'Dawno się nie odzywaliśmy. Jeśli nadal chcesz być blisko tego, co robimy, jesteśmy tutaj.', '', sign].join('\n')
    : [hello + ',', '', 'It has been a while. If you still want to stay close to what we are doing, we are here.', '', sign].join('\n');
} else if (key === 'crowdrelay.fan.first_ticket_thanks.v1') {
  subject = pl ? 'Dziękujemy za pierwszy bilet' : 'Thanks for your first ticket';
  text = pl
    ? [hello + ',', '', 'To Twój pierwszy bilet na ' + brand + '. Dziękujemy — do zobaczenia na koncercie.', '', sign].join('\n')
    : [hello + ',', '', 'That is your first ticket to see ' + brand + '. Thank you — see you at the show.', '', sign].join('\n');
} else if (key === 'crowdrelay.fan.returning_thanks.v1') {
  subject = pl ? 'Wracasz — i to zauważamy' : 'You keep coming back — we notice';
  text = pl
    ? [hello + ',', '', 'Byłeś z nami już kilka razy. Dziękujemy, że wracasz.', '', sign].join('\n')
    : [hello + ',', '', 'You have been with us more than once. Thanks for coming back.', '', sign].join('\n');
} else if (key === 'crowdrelay.fan.referral_thanks.v1') {
  subject = pl ? 'Ktoś dołączył dzięki Tobie' : 'Someone joined because of you';
  text = pl
    ? [hello + ',', '', 'Osoba, którą poleciłeś, właśnie dołączyła. Dziękujemy, że przyprowadzasz następnych.', '', sign].join('\n')
    : [hello + ',', '', 'Someone you referred just joined. Thanks for bringing another person in.', '', sign].join('\n');
} else if (key === 'crowdrelay.fan.referral_invite.v1') {
  if (!p.referral_url) throw new Error('referral_invite missing fan.referral_url');
  subject = pl ? ('Poleć komuś ' + brand) : ('Invite someone to ' + brand);
  text = pl
    ? [hello + ',', '', 'Jeśli znasz jedną osobę, której to może naprawdę siąść, wyślij jej swój link:', '', p.referral_url, '', 'Jeśli dołączy przez ten link, będziemy wiedzieć, że trafiła tu dzięki Tobie.', '', sign].join('\n')
    : [hello + ',', '', 'If you know one person this could genuinely be for, send them your link:', '', p.referral_url, '', 'If they join through it, we will know they found us through you.', '', sign].join('\n');
} else if (key === 'crowdrelay.fan.signal_install_ask.v1') {
  if (!p.install_url) throw new Error('signal_install_ask missing fan.install_url');
  subject = pl ? ('Signal — ' + brand + ' w Twojej kieszeni') : ('Signal — ' + brand + ' in your pocket');
  text = pl
    ? [hello + ',', '', 'Signal to nasze miejsce — koncerty, wiadomości i polecenia w jednym, zanim trafią gdziekolwiek indziej. Otwórz je tutaj:', '', p.install_url, '', sign].join('\n')
    : [hello + ',', '', 'Signal is our place — shows, news and referrals in one, before they land anywhere else. Open it here:', '', p.install_url, '', sign].join('\n');
} else if (key === 'crowdrelay.fan.show_recall.v1') {
  if (!p.show_url) throw new Error('show_recall missing fan.show_url');
  const install = p.install_url
    ? (pl
      ? ['', 'A jeśli Signal — nasze miejsce — nie jest jeszcze u Ciebie:', '', p.install_url]
      : ['', 'And if Signal — our place — is not on your phone yet:', '', p.install_url])
    : [];
  subject = pl ? 'Dziękujemy za wczoraj' : 'Thanks for last night';
  text = pl
    ? [hello + ',', '', 'Wczorajszy koncert — dziękujemy, że mogliśmy się spotkać. Strona wieczoru:', '', p.show_url, ...install, '', sign].join('\n')
    : [hello + ',', '', 'Last night — thank you for being in the room with us. The show page:', '', p.show_url, ...install, '', sign].join('\n');
} else {
  throw new Error('Unknown lifecycle template: ' + key);
}
return [{ json: { ...p, subject, text } }];
